    /**
     * Tests getting all Interviews.
     *
     * @return    Collection
     */
    public List<Interview> testGetAll() throws Throwable {
    LOGGER.info( "InterviewTest:testGetAll() - Retrieving Collection of Interviews:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Interview : " );
    List<Interview> collection  = null;

    try {
        // call the static get method on the InterviewService
        collection = service.getAllInterview();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Interview currEntity  = null;
            Iterator<Interview> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getInterviewId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

